// Initialize the random number generator (typically done with a proper seed)
    static bool seeded = false;
    if (!seeded) {
        std::srand(static_cast<unsigned int>(std::time(0)));
        seeded = true;
    }

    // Generate velocities from Maxwell-Boltzmann distribution
    double kB = 1.0;
    for (size_t i = 0; i < velocities.size(); ++i) {
        double sigma_v = std::sqrt(kB * temperature / masses[i]);

        // Box-Muller transform for Gaussian random numbers
        double u1 = static_cast<double>(std::rand()) / RAND_MAX;
        double u2 = static_cast<double>(std::rand()) / RAND_MAX;
        double z0 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
        double z1 = std::sqrt(-2.0 * std::log(u1)) * std::sin(2.0 * M_PI * u2);
        double z2 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);

        velocities[i] = vec3(z0 * sigma_v, z1 * sigma_v, z2 * sigma_v);
    }

    // Remove center of mass motion
    vec3 vcm(0, 0, 0);
    double totalMass = 0.0;
    for (size_t i = 0; i < velocities.size(); ++i) {
        vcm += velocities[i] * masses[i];
        totalMass += masses[i];
    }
    vcm /= totalMass;

    for (size_t i = 0; i < velocities.size(); ++i) {
        velocities[i] -= vcm;
    }
}

